Action.Str:
var stops = JSON.parse(global('BusStops'));
var i = (parseInt(global('BusIdx'), 10) + 1) % stops.length;
setGlobal('BusIdx', String(i));
setGlobal('BusStopId', stops[i].id);
setGlobal('BusStopName', stops[i].name);
setGlobal('BusDist', String(stops[i].dist));

var mine = global('BusRoutes').split(',');
var stops = JSON.parse(http_data).stopPoints
  .filter(function (s) {
    return s.lines.some(function (l) { return mine.indexOf(l.id) > -1; });
  })
  .sort(function (a, b) { return a.distance - b.distance; })
  .slice(0, 4)
  .map(function (s) {
    return { id: s.naptanId, name: s.commonName + ' (' + (s.indicator || 'stop') + ')', dist: Math.round(s.distance) };
  });
setGlobal('BusStops', JSON.stringify(stops));
setGlobal('BusIdx', '0');
if (stops.length) {
  setGlobal('BusStopId', stops[0].id);
  setGlobal('BusStopName', stops[0].name);
  setGlobal('BusDist', String(stops[0].dist));
}
var found = stops.length > 0 ? 'yes' : 'no';

var mine = global('BusRoutes').split(',');
var arr = JSON.parse(http_data)
  .filter(function (b) { return mine.indexOf(b.lineName) > -1; })
  .sort(function (x, y) { return x.timeToStation - y.timeToStation; })
  .slice(0, 4);
var FIG = '\u2007'; // figure space: same width as a digit
function bold(t) {  // Unicode bold digits/capitals survive where Android strips styling
  return String(t).replace(/[0-9A-Z]/g, function (c) {
    var n = c.charCodeAt(0);
    return String.fromCodePoint(c <= '9' ? 0x1D7EC + n - 48 : 0x1D5D4 + n - 65);
  });
}
function when(s) {
  var m = Math.round(s / 60);
  return m < 1 ? '🟢 Due' : (m < 10 ? FIG : '') + m + ' min';
}
function route(r) { var p = ''; for (var i = r.length; i < 3; i++) p += FIG; return p + bold(r); }
var bussummary = arr.length
  ? arr.map(function (b) { return b.lineName + ' ' + when(b.timeToStation).replace('🟢 ', '').toLowerCase().replace(FIG, ''); }).join(' | ')
  : 'No predictions right now';
var busrich = arr.length
  ? arr.map(function (b) { return route(b.lineName) + '   ' + when(b.timeToStation) + '   ' + b.destinationName; }).join('\n')
  : 'No predictions for your routes right now';
var busnext = arr.length ? String(Date.parse(arr[0].expectedArrival)) : '';
var bustime = new Date().toTimeString().slice(0, 5);
var busfirst = arr.length ? Math.round(arr[0].timeToStation / 60) : -1;
var buschip = busfirst < 0 ? 'No bus' : arr[0].lineName + ' ' + (busfirst < 1 ? 'now' : busfirst + 'm');
// --- floating pill (island around the camera): next bus per route, rotating, with a countdown ring ---
var V = '%';
function islandSetting(name, fallback) {
  var v = global(name);
  if (!v || String(v).charAt(0) === V) { setGlobal(name, String(fallback)); return fallback; }
  return parseInt(v, 10);
}
var islandH = islandSetting('BusIslandH', 30);
islandSetting('BusIslandY', 9);
islandSetting('BusIslandW', 278);
var islandGap = islandSetting('BusIslandGap', 42);

var rotateS = parseFloat(global('BusRotate'));
if (!(rotateS >= 2)) { rotateS = 6; setGlobal('BusRotate', '6'); }
var seenRoute = {}, perRoute = [], nowMs = Date.now();
JSON.parse(http_data)
  .filter(function (b) { return mine.indexOf(b.lineName) > -1; })
  .sort(function (x, y) { return x.timeToStation - y.timeToStation; })
  .forEach(function (b) {
    if (seenRoute[b.lineName]) return;
    seenRoute[b.lineName] = true;
    perRoute.push({ l: b.lineName, d: b.destinationName, t: nowMs + b.timeToStation * 1000 });
  });
setGlobal('BusPillData', JSON.stringify({ u: nowMs, r: 1000 * (parseInt(global('BusRefresh'), 10) || 45), rot: Math.round(rotateS * 1000), s: global('BusStopId'), n: global('BusStopName'), b: perRoute }));

var padX = Math.round(islandH * 0.3);
var leftW = Math.max(40, Math.round((global('BusIslandW') - islandGap - 2 * padX) / 2));
var pillHtml = [
'<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>',
'html,body{margin:0;height:' + islandH + 'px;background:transparent;overflow:hidden;-webkit-user-select:none;user-select:none;-webkit-tap-highlight-color:transparent}',
'body{font-family:system-ui,Roboto,sans-serif}',
'#p{position:relative;display:flex;align-items:center;height:' + islandH + 'px;box-sizing:border-box;padding:0 ' + padX + 'px;border-radius:' + (islandH / 2) + 'px;background:#000;color:#fff;font-size:14px;white-space:nowrap;touch-action:none}',
'#ring{position:absolute;left:0;top:0;overflow:visible;pointer-events:none}',
'.h{display:flex;align-items:center;gap:6px;min-width:0;overflow:hidden;transition:opacity .18s,transform .18s}',
'#L{flex:none;width:' + leftW + 'px}#R{flex:none}',
'#probe{position:absolute;left:-9999px;top:0;visibility:hidden;display:flex;align-items:center;gap:6px;white-space:nowrap;font-size:14px}',
'#p.out .h{opacity:0;transform:translateX(-6px)}#p.back .h{opacity:0;transform:translateX(6px)}',
'#g{flex:none;width:' + islandGap + 'px}',
'.b{background:#DC241F;border-radius:99px;padding:1px 7px;font-weight:700;font-size:13px;flex:none}',
'.m{font-weight:700;flex:none}.m.due{color:#7FD6A4}',
'.d{color:#B7BFCD;font-size:12px;overflow:hidden;text-overflow:ellipsis;min-width:0}',
'.s{font-weight:700;overflow:hidden;text-overflow:ellipsis;min-width:0}',
'.dots{display:flex;gap:3px;flex:none}.dots i{width:4px;height:4px;border-radius:2px;background:#5A6376}.dots i.on{background:#fff}',
'</style></head><body>',
'<div id="d" hidden>' + V + 'BusPillData</div>',
'<div id="probe"></div><div id="p"><svg id="ring"><rect id="track"/><rect id="prog"/></svg><div class="h" id="L"></div><div id="g"></div><div class="h e" id="R"></div></div>',
'<script>',
'var ROT=6000,HOLD=550,SWIPE=24,LW=' + leftW + ',GAP=' + islandGap + ',PAD=' + padX + ',lastW=0;',
'var data=null,raw="",idx=0,start=Date.now(),lastStop=null,flashUntil=0;',
'var dEl=document.getElementById("d"),p=document.getElementById("p"),L=document.getElementById("L"),R=document.getElementById("R");',
'var ring=document.getElementById("ring"),track=document.getElementById("track"),prog=document.getElementById("prog");',
'function list(){return data&&data.b?data.b:[];}',
'function rot(){return (data&&data.rot)||ROT;}',
'function read(){var t=dEl.textContent.trim();if(t===raw)return;raw=t;try{data=JSON.parse(t);}catch(e){return;}',
' if(data.s!==lastStop){if(lastStop!==null){flashUntil=Date.now()+1200;setTimeout(draw,1250);}lastStop=data.s;idx=0;}',
' if(idx>=list().length)idx=0;start=Date.now();draw();}',
'function mins(ms){var m=Math.round((ms-Date.now())/60000);return m<1?"Due":m+" min";}',
'function esc(s){return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;");}',
'function rightHtml(b,on){var c=list().length,mm=mins(b.t),dots="";',
' if(c>1){dots="<span class=\\"dots\\">";for(var i=0;i<c;i++)dots+="<i"+(i===on?" class=\\"on\\"":"")+"></i>";dots+="</span>";}',
' return "<span class=\\"m"+(mm==="Due"?" due":"")+"\\">"+mm+"</span>"+dots;}',
'function fit(){var probe=document.getElementById("probe"),rw=24,bs=list();',
' for(var i=0;i<bs.length;i++){probe.innerHTML=rightHtml(bs[i],i);rw=Math.max(rw,Math.ceil(probe.scrollWidth));}',
' R.style.width=rw+"px";var w=PAD+LW+GAP+rw+PAD,x=Math.round(screen.width/2-GAP/2-LW-PAD);',
' if(Math.abs(w-lastW)>=2&&window.Tasker&&Tasker.updateOverlayConfig){lastW=w;Tasker.updateOverlayConfig({x:String(x),width:String(w)});}}',
'function draw(){',
' if(Date.now()<flashUntil){var n=(data&&data.n)||"",mt=n.match(/^(.*) \\((.*)\\)$/);',
'  L.innerHTML="<span class=\\"s\\">"+esc(mt?mt[2]:n)+"</span>";R.innerHTML="<span class=\\"s\\">"+esc(mt?mt[1]:"")+"</span>";size();return;}',
' var c=list().length;if(!c){L.innerHTML="<span class=\\"s\\">No buses</span>";R.innerHTML="";fit();size();return;}',
' var b=list()[idx],mm=mins(b.t),dots="";',
' if(c>1){dots="<span class=\\"dots\\">";for(var i=0;i<c;i++)dots+="<i"+(i===idx?" class=\\"on\\"":"")+"></i>";dots+="</span>";}',
' L.innerHTML="<span class=\\"b\\">"+esc(b.l)+"</span><span class=\\"d\\">"+esc(b.d)+"</span>";',
' R.innerHTML=rightHtml(b,idx);fit();size();}',
'function size(){var w=p.offsetWidth,h=p.offsetHeight;ring.setAttribute("width",w);ring.setAttribute("height",h);ring.setAttribute("viewBox","0 0 "+w+" "+h);',
' [track,prog].forEach(function(r){r.setAttribute("x",1);r.setAttribute("y",1);r.setAttribute("width",w-2);r.setAttribute("height",h-2);r.setAttribute("rx",(h-2)/2);r.setAttribute("fill","none");r.setAttribute("stroke-width",1.5);r.setAttribute("pathLength",100);});',
' track.setAttribute("stroke","rgba(255,255,255,0.10)");prog.setAttribute("stroke","rgba(255,255,255,0.8)");prog.setAttribute("stroke-dasharray","100 100");}',
'function go(step){var c=list().length;if(c<2)return;idx=idx+step;if(idx>=c)idx=0;if(idx<0)idx=c-1;',
' var cls=step>0?"out":"back";p.classList.add(cls);setTimeout(function(){draw();p.classList.remove(cls);},180);start=Date.now();}',
'function tick(){var multi=list().length>1,dur=multi?rot():((data&&data.r)||45000),from=multi?start:((data&&data.u)||start),el=Date.now()-from;',
' var f=Math.max(0,Math.min(1,1-el/dur));prog.setAttribute("stroke-dashoffset",String(100-100*f));',
' if(multi&&el>=rot())go(1);requestAnimationFrame(tick);}',
'function run(n){if(window.Tasker&&Tasker.runTask)Tasker.runTask({name:n});}',
'var sx=0,sy=0,held=false,ht=null;',
'p.addEventListener("touchstart",function(e){var t=e.touches[0];sx=t.clientX;sy=t.clientY;held=false;ht=setTimeout(function(){held=true;if(navigator.vibrate)navigator.vibrate(20);run("Bus Other Side");},HOLD);},{passive:true});',
'p.addEventListener("touchmove",function(e){var t=e.touches[0];if(Math.abs(t.clientX-sx)>10||Math.abs(t.clientY-sy)>10)clearTimeout(ht);},{passive:true});',
'p.addEventListener("touchend",function(e){clearTimeout(ht);if(held)return;var t=e.changedTouches[0],dx=t.clientX-sx,dy=t.clientY-sy;',
' if(Math.abs(dx)>SWIPE&&Math.abs(dx)>Math.abs(dy)){go(dx<0?1:-1);return;}',
' if(dy<-SWIPE&&Math.abs(dy)>Math.abs(dx))run("Bus Stop");});',
'new MutationObserver(read).observe(dEl,{childList:true,characterData:true,subtree:true});',
'window.addEventListener("resize",size);setInterval(read,1000);setInterval(draw,15000);read();requestAnimationFrame(tick);',
'<\/script></body></html>'
].join('\n');

var layout = {
  name: 'Bus Pill',
  defaultDisplayMode: 'Overlay',
  root: {
    // Rounded clip at both ends keeps the web view's corners see-through (proven in Pill Test 2)
    type: 'Box', id: 'root',
    modifiers: [
      { type: 'FillSize' },
      { type: 'Clip', shape: 'Rounded', radius: '50' },
      { type: 'Clip', shape: 'Rounded', radius: '50' }
    ],
    children: [{
      type: 'WebView', id: 'pillweb', content: pillHtml,
      backgroundColor: 'transparent', darkMode: 'ForceLight', supportZoom: 'false',
      modifiers: [{ type: 'FillSize' }]
    }]
  }
};
setGlobal('BusPillLayout', JSON.stringify(layout));

var r = parseInt(global('BusRefresh'), 10);
if (!(r >= 15)) { r = 45; setGlobal('BusRefresh', '45'); }
var t = parseFloat(global('BusTimeout'));
if (!(t > 0)) { t = 30; setGlobal('BusTimeout', '30'); }
var busrefresh = String(r);
var buscycles = String(Math.max(1, Math.round(t * 60 / r)));

var V = '%';
function g(n) { var v = global(n); return (v === undefined || v === null || String(v).charAt(0) === V) ? '' : String(v); }
var mine = g('BusRoutes').split(',');
var sp = (JSON.parse(http_data).stopPoints || []).sort(function (a, b) { return a.distance - b.distance; });
var best = sp.filter(function (s) { return s.lines.some(function (l) { return mine.indexOf(l.id) > -1; }); })[0] || sp[0];
var busadded;
if (!best) {
  busadded = 'No bus stop within 60 m';
} else {
  var name = best.commonName + (best.indicator ? ' (' + best.indicator + ')' : '');
  var rows = g('BusStopList') ? g('BusStopList').split('\n') : [];
  if (rows.some(function (r) { return r.split('|')[0] === best.naptanId; })) {
    busadded = name + ' is already saved';
  } else {
    rows.push([best.naptanId, name, best.lat, best.lon].join('|'));
    setGlobal('BusStopList', rows.join('\n'));
    busadded = 'Saved ' + name + ' (' + rows.length + (rows.length === 1 ? ' stop' : ' stops') + ' in your list)';
  }
}

var V = '%';
function g(n) { var v = global(n); return (v === undefined || v === null || String(v).charAt(0) === V) ? '' : String(v); }
var busdue = (g('BusStopList') !== '' && Date.now() >= (parseInt(g('BusWatchNext'), 10) || 0)) ? 'yes' : 'no';

var V = '%';
function g(n) { var v = global(n); return (v === undefined || v === null || String(v).charAt(0) === V) ? '' : String(v); }
var lat = parseFloat(gl_latitude), lon = parseFloat(gl_longitude), now = Date.now();
var busaction = 'none', d = Infinity;
if (!isNaN(lat) && !isNaN(lon)) {
  g('BusStopList').split('\n').forEach(function (row) {
    var p = row.split('|'); if (p.length < 4) return;
    var sl = parseFloat(p[2]), so = parseFloat(p[3]), r = Math.PI / 180;
    var x = (so - lon) * r * Math.cos((sl + lat) / 2 * r), y = (sl - lat) * r;
    d = Math.min(d, Math.sqrt(x * x + y * y) * 6371000);
  });
  var enterR = parseFloat(g('BusNearRadius')) || 60, exitR = enterR * 1.6;
  var running = g('BusRun') === '1', auto = g('BusAuto') === '1';
  if (d <= enterR && !auto && !running) { busaction = 'start'; setGlobal('BusAuto', '1'); }
  else if (d > exitR && auto) { setGlobal('BusAuto', '0'); if (running) busaction = 'stop'; }
}
// Check less often the further away the nearest saved stop is
var waitMin = d > 2000 ? 10 : d > 800 ? 5 : d > 300 ? 2 : 0;
if (d === Infinity) waitMin = 2;
setGlobal('BusWatchNext', String(now + waitMin * 60000 - 15000));
var busdist = d === Infinity ? '?' : String(Math.round(d));

var V = '%';
function g(n) { var v = global(n); return (v === undefined || v === null || String(v).charAt(0) === V) ? '' : String(v); }
var r = parseInt(g('BusAddRadius'), 10);
if (!(r >= 50)) { r = 400; setGlobal('BusAddRadius', '400'); }
var busradius = String(Math.min(r, 2000));

var V = '%';
function g(n) { var v = global(n); return (v === undefined || v === null || String(v).charAt(0) === V) ? '' : String(v); }
var mine = g('BusRoutes').split(',');
var saved = g('BusStopList').split('\n').map(function (r) { return r.split('|')[0]; });
function clean(t) { return String(t).replace(/\s*,\s*/g, ' '); }
var choices = (JSON.parse(http_data).stopPoints || [])
  .map(function (s) {
    var mineHere = s.lines.map(function (l) { return l.id; }).filter(function (id) { return mine.indexOf(id) > -1; });
    return { s: s, routes: mineHere };
  })
  .filter(function (c) { return c.routes.length > 0 && saved.indexOf(c.s.naptanId) < 0; })
  .sort(function (a, b) { return a.s.distance - b.s.distance; })
  .slice(0, 15)
  .map(function (c) {
    var name = clean(c.s.commonName + (c.s.indicator ? ' (' + c.s.indicator + ')' : ''));
    return {
      label: name + ' \u2013 ' + Math.round(c.s.distance) + ' m \u2013 ' + c.routes.join('/'),
      row: [c.s.naptanId, name, c.s.lat, c.s.lon].join('|'),
      name: name
    };
  });
setGlobal('BusAddChoices', JSON.stringify(choices));
var busitems = choices.map(function (c) { return c.label; }).join(',');
var buscount = String(choices.length);

var V = '%';
function g(n) { var v = global(n); return (v === undefined || v === null || String(v).charAt(0) === V) ? '' : String(v); }
var picked = (typeof ld_selected === 'undefined' ? '' : String(ld_selected));
var choices = JSON.parse(g('BusAddChoices') || '[]');
var hit = choices.filter(function (c) { return c.label === picked; })[0];
var busadded;
if (!hit) {
  busadded = 'Nothing saved';
} else {
  var rows = g('BusStopList') ? g('BusStopList').split('\n') : [];
  rows.push(hit.row);
  setGlobal('BusStopList', rows.join('\n'));
  busadded = 'Saved ' + hit.name + ' (' + rows.length + (rows.length === 1 ? ' stop' : ' stops') + ' in your list)';
}
setGlobal('BusAddChoices', '');
